import type { BoardDescription } from './boardCode.ts';

export function nextParkMiller(state: number): number {
  // The largest product is below 2^53, so every integer is exact.
  return (state * 16807) % 2147483647;
}

export function generateDeck(board: BoardDescription): readonly number[] {
  const deck = Array.from({ length: board.size ** 2 }, (_, i) => Math.floor(i / 2));
  let state = board.seed;
  function draw(bound: number): number {
    const limit = Math.floor(2147483646 / bound) * bound;
    do { state = nextParkMiller(state); } while (state - 1 >= limit);
    return (state - 1) % bound;
  }
  for (let i = deck.length - 1; i > 0; i--) {
    const j = draw(i + 1);
    const first = deck[i];
    const second = deck[j];
    if (first !== undefined && second !== undefined) {
      deck[i] = second;
      deck[j] = first;
    }
  }
  return Object.freeze(deck);
}

/work/src/game/replay.ts.content:
import { hasKeys, isInteger, isRecord, readJSON } from './formatValidation.ts';
import { activateCard, advanceGame } from './rules.ts';
import { createGame } from './state.ts';
import type { GameState } from './state.ts';

export const REPLAY_VERSION = 1;
export const REPLAY_BYTES = 1048576;
export const REPLAY_ACTIONS = 10000;

export function replayGame(text: string): GameState | null {
  const value = readJSON(text, REPLAY_BYTES);
  if (!isRecord(value) || !hasKeys(value, ['version', 'boardCode', 'actions', 'endMs']) ||
      value.version !== REPLAY_VERSION || typeof value.boardCode !== 'string' ||
      !Array.isArray(value.actions) || value.actions.length > REPLAY_ACTIONS ||
      !isInteger(value.endMs)) return null;
  let game = createGame(value.boardCode);
  if (!game) return null;
  let previousMs = 0;
  for (const action of value.actions) {
    if (!isRecord(action) || !hasKeys(action, ['atMs', 'index']) ||
        !isInteger(action.atMs) || action.atMs < previousMs ||
        !isInteger(action.index, game.deck.length - 1)) return null;
    game = activateCard(advanceGame(game, action.atMs - previousMs), action.index);
    previousMs = action.atMs;
  }
  if (value.endMs < previousMs) return null;
  return advanceGame(game, value.endMs - previousMs);
}

/work/src/game/state.ts.content:
import { parseBoardCode } from './boardCode.ts';
import type { BoardDescription } from './boardCode.ts';
import { generateDeck } from './deck.ts';

export const SELECTION = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
export type Selection =
  | { readonly kind: typeof SELECTION.closed }
  | { readonly kind: typeof SELECTION.one; readonly index: number }
  | { readonly kind: typeof SELECTION.mismatch; readonly first: number;
      readonly second: number; readonly remainingMs: number };

export interface GameState {
  readonly board: BoardDescription;
  readonly deck: readonly number[];
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  return board ? {
    board, deck: generateDeck(board), matched: [], selection: { kind: SELECTION.closed },
    moves: 0, elapsedMs: 0, started: false,
  } : null;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}

export function isRevealed(state: GameState, index: number): boolean {
  if (state.matched.includes(index)) return true;
  const selection = state.selection;
  switch (selection.kind) {
    case SELECTION.closed: return false;
    case SELECTION.one: return selection.index === index;
    case SELECTION.mismatch: return selection.first === index || selection.second === index;
  }
}

/work/src/game/boardCode.ts.content:
export const SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export type Size = (typeof SIZES)[number];
export const MAX_SEED = 2147483646;
export interface BoardDescription {
  readonly code: string;
  readonly size: Size;
  readonly seed: number;
}

export function isSize(value: unknown): value is Size {
  return SIZES.some(size => size === value);
}

export function parseBoardCode(code: string): BoardDescription | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]{0,9})$/.exec(code);
  if (!match || match[0] !== code) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!isSize(size) || seed > MAX_SEED) return null;
  return Object.freeze({ code, size, seed });
}

