import { useCallback, useLayoutEffect, useRef } from 'react';

// All time comes from one monotonic clock. Checkpoints also run before actions,
// so a late render cannot change turn ordering or an exported snapshot.
export function useActiveClock(enabled: boolean, generation: number, advance: (ms: number) => void) {
  const clock = useRef({ active: false, last: 0 });
  const settle = useCallback(() => {
    const now = performance.now();
    const { active, last } = clock.current;
    clock.current.last = now;
    if (active) advance(Math.max(0, now - last));
  }, [advance]);

  useLayoutEffect(() => {
    let valid = true;
    let timer: ReturnType<typeof setTimeout> | undefined;
    clock.current = { active: enabled && !document.hidden, last: performance.now() };
    function schedule() {
      if (valid && clock.current.active) timer = setTimeout(tick, 25);
    }
    function tick() {
      if (!valid) return;
      settle();
      schedule();
    }
    function visibility() {
      if (!valid) return;
      settle();
      if (timer !== undefined) clearTimeout(timer);
      clock.current.active = enabled && !document.hidden;
      schedule();
    }
    document.addEventListener('visibilitychange', visibility);
    schedule();
    return () => {
      valid = false;
      clock.current.active = false;
      if (timer !== undefined) clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibility);
    };
  }, [enabled, generation, settle]);

  return settle;
}

