/work/tests/touch-scroll.spec.ts.content:
import { expect, test } from '@playwright/test';
import { cards, loadBoard } from './journey.ts';

test('16x16 first and last cards are reachable by touch scrolling on a phone', async ({ browser }) => {
  const context = await browser.newContext({ hasTouch: true, isMobile: true,
    viewport: { width: 360, height: 800 } });
  const page = await context.newPage();
  await page.goto('http://127.0.0.1:4173');
  await loadBoard(page, 'np1-16-1');
  await cards(page).first().tap();
  const scroll = page.locator('.board-scroll');
  await scroll.scrollIntoViewIfNeeded();
  const bounds = await scroll.boundingBox();
  if (!bounds) throw new Error('Missing scroll area.');
  const cdp = await context.newCDPSession(page);
  const gesture = { x: bounds.x + bounds.width / 2, y: bounds.y + bounds.height / 2,
    gestureSourceType: 'touch', speed: 1200 } as const;
  await cdp.send('Input.synthesizeScrollGesture', { ...gesture, xDistance: -1000, yDistance: 0 });
  await cdp.send('Input.synthesizeScrollGesture', { ...gesture, xDistance: 0, yDistance: -1000 });
  const atEnd = await scroll.evaluate(element =>
    element.scrollLeft + element.clientWidth >= element.scrollWidth - 1 &&
    element.scrollTop + element.clientHeight >= element.scrollHeight - 1);
  expect(atEnd).toBe(true);
  await cards(page).last().tap();
  await expect(page.getByText('Moves: 1', { exact: true })).toBeVisible();
  await context.close();
});

